package main

import (
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	plugin "github.com/SemRels/updater-replace/internal/plugin"
)

const pluginSchemaVersion = 1

func main() {
	os.Exit(run(os.Stdout, os.Stderr, os.Getenv))
}

func run(stdout, stderr io.Writer, getenv func(string) string) int {
	_, _ = fmt.Fprintf(stderr, "plugin_schema_version=%d\n", pluginSchemaVersion)

	rules, err := plugin.ParseRules(getenv("SEMREL_PLUGIN_REPLACEMENTS"), plugin.FlatConfig{
		Files:   getenv("SEMREL_PLUGIN_FILES"),
		Ignore:  getenv("SEMREL_PLUGIN_IGNORE"),
		From:    getenv("SEMREL_PLUGIN_FROM"),
		To:      getenv("SEMREL_PLUGIN_TO"),
		Literal: parseBool(getenv("SEMREL_PLUGIN_LITERAL")),
		Flags:   getenv("SEMREL_PLUGIN_FLAGS"),
		CountMatches: parseBool(firstNonEmpty(
			getenv("SEMREL_PLUGIN_COUNT_MATCHES"),
			getenv("SEMREL_PLUGIN_COUNTMATCHES"),
		)),
	})
	if err != nil {
		fmt.Fprintln(stderr, "updater-replace:", err)
		return 1
	}

	root, err := os.Getwd()
	if err != nil {
		fmt.Fprintln(stderr, "updater-replace:", err)
		return 1
	}

	result, err := plugin.Apply(plugin.Config{
		Root:   root,
		Rules:  rules,
		DryRun: parseBool(getenv("SEMREL_DRY_RUN")) || parseBool(getenv("SEMREL_PLUGIN_DRY_RUN")),
		Template: plugin.TemplateData{
			NextVersion: normalizeVersion(
				firstNonEmpty(getenv("SEMREL_VERSION"), getenv("SEMREL_NEXT_VERSION")),
				getenv("SEMREL_TAG_PREFIX"),
			),
			CurrentVersion: normalizeVersion(getenv("SEMREL_CURRENT_VERSION"), getenv("SEMREL_TAG_PREFIX")),
			TagName:        getenv("SEMREL_TAG_NAME"),
			Branch:         getenv("SEMREL_BRANCH"),
			Date:           time.Now().UTC().Format(time.DateOnly),
			Variables: map[string]string{
				"SEMREL_VERSION":         getenv("SEMREL_VERSION"),
				"SEMREL_NEXT_VERSION":    getenv("SEMREL_NEXT_VERSION"),
				"SEMREL_CURRENT_VERSION": getenv("SEMREL_CURRENT_VERSION"),
				"SEMREL_TAG_NAME":        getenv("SEMREL_TAG_NAME"),
				"SEMREL_BRANCH":          getenv("SEMREL_BRANCH"),
			},
		},
	})
	if err != nil {
		fmt.Fprintln(stderr, "updater-replace:", err)
		return 1
	}

	for _, file := range result.Files {
		if result.DryRun && file.Changed {
			_, _ = fmt.Fprintf(stderr, "[dry-run] updater-replace: would update %s (matches=%d replacements=%d)\n",
				file.Path, file.NumMatches, file.NumReplacements)
			continue
		}
		action := "unchanged"
		if file.Changed {
			action = "updated"
		}
		_, _ = fmt.Fprintf(stderr, "updater-replace: %s %s (matches=%d replacements=%d)\n",
			action, file.Path, file.NumMatches, file.NumReplacements)
	}
	if result.DryRun {
		_, _ = io.WriteString(stdout, result.UnifiedDiff())
		return 0
	}
	if len(result.ModifiedFiles()) > 0 {
		_, _ = fmt.Fprintf(stdout, "%s\n", strings.Join(result.ModifiedFiles(), "\n"))
	}
	return 0
}

func parseBool(raw string) bool {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "1", "true", "yes", "on":
		return true
	default:
		return false
	}
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

func normalizeVersion(version, prefix string) string {
	if prefix != "" {
		return strings.TrimPrefix(version, prefix)
	}
	return strings.TrimPrefix(version, "v")
}
